#!/usr/bin/env node
/**
 * Extract paragraph text from .docx files and save to a text file.
 *
 * .docx files are ZIP archives containing word/document.xml.
 * Paragraphs are in <w:p> elements; text runs are in <w:r><w:t> elements.
 *
 * Usage:  node scripts/extract_paragraphs.mjs [input.docx ...] [-o output.txt]
 * Defaults: all .docx in testbed/docs/, output to data/extracted_paragraphs.txt
 */

import { readFileSync, writeFileSync, readdirSync } from "fs";
import { resolve, basename } from "path";
import { execSync } from "child_process";

// ── Parse args ──────────────────────────────────────────────────────────────
const args = process.argv.slice(2);
let outputPath = resolve("/workspace/data/extracted_paragraphs.txt");
let inputFiles = [];

for (let i = 0; i < args.length; i++) {
  if (args[i] === "-o" && args[i + 1]) {
    outputPath = resolve(args[++i]);
  } else {
    inputFiles.push(resolve(args[i]));
  }
}

// Default: all .docx in testbed/docs/
if (inputFiles.length === 0) {
  const dir = "/workspace/testbed/docs";
  inputFiles = readdirSync(dir)
    .filter((f) => f.endsWith(".docx"))
    .sort()
    .map((f) => resolve(dir, f));
}

// ── Extract paragraphs from a .docx buffer ──────────────────────────────────
import { createRequire } from "module";
import zlib from "zlib";

/**
 * Minimal ZIP reader – enough for .docx (which uses DEFLATE or STORE).
 * Reads the Central Directory to locate word/document.xml, then decompresses.
 */
function readZipEntry(buf, entryName) {
  // Find End of Central Directory record (last 22+ bytes)
  let eocdOffset = -1;
  for (let i = buf.length - 22; i >= 0; i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) {
      eocdOffset = i;
      break;
    }
  }
  if (eocdOffset === -1) throw new Error("Not a valid ZIP file");

  const cdOffset = buf.readUInt32LE(eocdOffset + 16);
  const cdEntries = buf.readUInt16LE(eocdOffset + 10);

  let pos = cdOffset;
  for (let i = 0; i < cdEntries; i++) {
    if (buf.readUInt32LE(pos) !== 0x02014b50) throw new Error("Bad CD entry");
    const compMethod = buf.readUInt16LE(pos + 10);
    const compSize = buf.readUInt32LE(pos + 20);
    const uncompSize = buf.readUInt32LE(pos + 24);
    const nameLen = buf.readUInt16LE(pos + 28);
    const extraLen = buf.readUInt16LE(pos + 30);
    const commentLen = buf.readUInt16LE(pos + 32);
    const localHeaderOffset = buf.readUInt32LE(pos + 42);
    const name = buf.toString("utf8", pos + 46, pos + 46 + nameLen);

    if (name === entryName) {
      // Jump to local file header to find actual data start
      const lh = localHeaderOffset;
      if (buf.readUInt32LE(lh) !== 0x04034b50) throw new Error("Bad local header");
      const lhNameLen = buf.readUInt16LE(lh + 26);
      const lhExtraLen = buf.readUInt16LE(lh + 28);
      const dataStart = lh + 30 + lhNameLen + lhExtraLen;
      const raw = buf.subarray(dataStart, dataStart + compSize);

      if (compMethod === 0) return raw;                         // STORE
      if (compMethod === 8) return zlib.inflateRawSync(raw);    // DEFLATE
      throw new Error(`Unsupported compression method ${compMethod}`);
    }

    pos += 46 + nameLen + extraLen + commentLen;
  }
  throw new Error(`Entry "${entryName}" not found in ZIP`);
}

/**
 * Parse paragraph text out of the raw XML of word/document.xml.
 * Uses a simple regex approach (no XML parser needed for this structure).
 */
function parseParagraphs(xml) {
  const paragraphs = [];
  // Match each <w:p ...>...</w:p> (non-greedy, dotall)
  const pRegex = /<w:p[\s>][\s\S]*?<\/w:p>/g;
  let pMatch;
  while ((pMatch = pRegex.exec(xml)) !== null) {
    const pXml = pMatch[0];
    // Collect all <w:t ...>text</w:t> within this paragraph
    const tRegex = /<w:t[^>]*>([\s\S]*?)<\/w:t>/g;
    let text = "";
    let tMatch;
    while ((tMatch = tRegex.exec(pXml)) !== null) {
      text += tMatch[1];
    }
    // Keep only non-empty paragraphs
    if (text.trim().length > 0) {
      paragraphs.push(text);
    }
  }
  return paragraphs;
}

// ── Main ────────────────────────────────────────────────────────────────────
const allOutput = [];

for (const filePath of inputFiles) {
  const fileName = basename(filePath);
  console.log(`Processing: ${fileName}`);

  const buf = readFileSync(filePath);
  const xmlBuf = readZipEntry(buf, "word/document.xml");
  const xml = xmlBuf.toString("utf8");
  const paragraphs = parseParagraphs(xml);

  allOutput.push(`${"=".repeat(60)}`);
  allOutput.push(`FILE: ${fileName}`);
  allOutput.push(`${"=".repeat(60)}`);
  paragraphs.forEach((p, i) => {
    allOutput.push(`[${i + 1}] ${p}`);
  });
  allOutput.push("");

  console.log(`  → ${paragraphs.length} paragraphs extracted`);
}

writeFileSync(outputPath, allOutput.join("\n"), "utf8");
console.log(`\nAll paragraphs saved to: ${outputPath}`);

